                    <div class="liq-bar short-bar" :style="{width: (s.density * 100) + '%'}"></div>
                  </div>
                  <span class="liq-h-price">{{ s.price }}</span>
                </div>
              </div>
            </div>
          </div>
          <div class="liq-danger">
            <div class="liq-danger-title">
              <el-icon><Warning /></el-icon>
              爆仓危险价位
            </div>
            <div v-if="!liqHeatmap.danger_levels || liqHeatmap.danger_levels.length === 0" class="mf-empty">
