              <span class="liq-danger-price">{{ d.price }}</span>
              <span class="liq-danger-dist">距当前 {{ d.distance_pct }}%</span>
              <div class="liq-danger-bar" :style="{width: (d.density * 100) + '%'}"></div>
            </div>
          </div>
