                      <template #dropdown>
                        <el-dropdown-menu>
                          <el-dropdown-item command="classic">📐 经典三栏</el-dropdown-item>
                          <el-dropdown-item command="compact">📊 紧凑全屏</el-dropdown-item>
                          <el-dropdown-item command="focus">🎯 K线聚焦</el-dropdown-item>
                          <el-dropdown-item command="dashboard">📈 仪表盘</el-dropdown-item>
                          <el-dropdown-item command="custom">✨ 自定义拖拽</el-dropdown-item>
                        </el-dropdown-menu>
                      </template>
                    </el-dropdown>
                    <el-button size="small" :type="layoutEditMode ? 'success' : 'warning'" @click="toggleEditMode">
                      {{ layoutEditMode ? '完成编辑' : '编辑布局' }}
                    </el-button>
