                      <el-button size="small" type="primary">+ 添加面板</el-button>
                      <template #dropdown>
                        <el-dropdown-menu>
                          <el-dropdown-item v-for="pid in availablePanels" :key="pid" :command="pid">
                            {{ allPanelsConfig[pid]?.title || pid }}
                          </el-dropdown-item>
                        </el-dropdown-menu>
                      </template>
                    </el-dropdown>
                    <el-button size="small" @click="resetLayout">重置</el-button>
                    <el-dropdown trigger="click" @command="onCloudLayoutCommand">
