                        <el-icon class="el-icon--right"><ArrowDown /></el-icon>
                      </el-button>
                      <template #dropdown>
                        <el-dropdown-menu>
                          <el-dropdown-item command="save-my">💾 保存为我的布局</el-dropdown-item>
                          <el-dropdown-item command="save-public" v-if="userRole === 'admin'">🌐 发布为公共布局</el-dropdown-item>
                          <el-dropdown-item divided disabled>📂 我的布局</el-dropdown-item>
                          <el-dropdown-item v-for="l in myLayouts" :key="'my-'+l.id" :command="'load-my:'+l.id">
