                          </el-dropdown-item>
                          <el-dropdown-item v-if="myLayouts.length === 0" disabled>&nbsp;&nbsp;暂无保存</el-dropdown-item>
                          <el-dropdown-item divided disabled>🌐 公共布局</el-dropdown-item>
                          <el-dropdown-item v-for="l in publicLayouts" :key="'pub-'+l.id" :command="'load-public:'+l.id">
                            &nbsp;&nbsp;{{ l.is_default ? '⭐ ' : '' }}{{ l.name }}
