                  <div class="ob-header-sm"><span>价格</span><span>数量</span><span>累计</span></div>
                  <div class="ob-asks-sm">
                    <div v-for="(a, i) in orderbook.asks.slice().reverse()" :key="'a'+i" class="ob-row-sm ask">
                      <div class="ob-price-sm ask-price">{{ fmtMoney(a.price, 4) }}</div>
                      <div class="ob-qty-sm">{{ a.quantity.toFixed(4) }}</div>
                      <div class="ob-total-sm">{{ a.total.toFixed(2) }}</div>
                      <div class="ob-bg-sm ask-bg" :style="{width: getObPct(a.total, 'ask') + '%'}"></div>
                    </div>
                  </div>
                  <div class="ob-spread-sm"><span class="spread-label">价差</span><span class="spread-value">{{ fmtMoney(spread, 4) }}</span></div>
                  <div class="ob-bids-sm">
                    <div v-for="(b, i) in orderbook.bids" :key="'b'+i" class="ob-row-sm bid">
                      <div class="ob-price-sm bid-price">{{ fmtMoney(b.price, 4) }}</div>
                      <div class="ob-qty-sm">{{ b.quantity.toFixed(4) }}</div>
                      <div class="ob-total-sm">{{ b.total.toFixed(2) }}</div>
                      <div class="ob-bg-sm bid-bg" :style="{width: getObPct(b.total, 'bid') + '%'}"></div>
                    </div>
                  </div>
                </div>
              </template>
              <!-- 近期成交 -->
              <template v-else-if="item.i === 'trades'">
                <div class="side-title-sm"><span class="status-light ok" style="margin:0;width:5px;height:5px;"></span>近期成交</div>
                <div class="trades-header-sm"><span>价格</span><span>数量</span><span>时间</span></div>
                <div class="trades-list-sm">
                  <div v-for="(t, i) in recentTrades.slice(0, 15)" :key="t.trade_id || i" class="trade-row-sm"
                       :class="[t.side === 1 ? 'buy' : 'sell']">
                    <span class="trade-price-sm"><span class="status-light" :class="t.side === 1 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span><span class="trade-arrow-sm">{{ t.side === 1 ? '&#9650;' : '&#9660;' }}</span>{{ fmtMoney(t.price, 4) }}</span>
                    <span class="trade-qty-sm">{{ t.quantity.toFixed(4) }}</span>
                    <span class="trade-time-sm">{{ formatTime(t.timestamp_ms) }}</span>
                  </div>
                </div>
              </template>
              <!-- 清算热力图 -->
              <template v-else-if="item.i === 'liqheatmap'">
                <div class="side-title-sm"><span class="status-light ok" style="margin:0;"></span>清算热力图</div>
                <div class="liq-chart-horizontal liq-chart-sm">
                  <div class="liq-h-side liq-h-long">
                    <div class="liq-h-title-sm">多头爆仓</div>
                    <div class="liq-h-bars-sm">
                      <div v-for="(l, i) in liqHeatmap.long_liq.slice().reverse()" :key="'l'+i" class="liq-h-bar-item-sm">
                        <span class="liq-h-price-sm">{{ l.price }}</span>
                        <div class="liq-h-bar-wrap-sm">
                          <div class="liq-bar-sm long-bar" :style="{width: (l.density * 100) + '%'}"></div>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div class="liq-h-center-sm">
                    <div class="liq-h-center-label-sm">当前价</div>
                    <div class="liq-h-center-price-sm">{{ fmtMoney(trend.last_price, 4) }}</div>
                  </div>
                  <div class="liq-h-side liq-h-short">
                    <div class="liq-h-title-sm">空头爆仓</div>
                    <div class="liq-h-bars-sm">
                      <div v-for="(s, i) in liqHeatmap.short_liq" :key="'s'+i" class="liq-h-bar-item-sm">
                        <div class="liq-h-bar-wrap-sm liq-h-bar-right-sm">
                          <div class="liq-bar-sm short-bar" :style="{width: (s.density * 100) + '%'}"></div>
                        </div>
                        <span class="liq-h-price-sm">{{ s.price }}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </template>
              <!-- 主力位置分析 -->
              <template v-else-if="item.i === 'mainforce'">
                <div class="info-title-sm">主力位置 <span class="info-badge-sm" :class="mainForce.pressure"><span class="status-light" :class="mainForce.pressure === 'bullish' ? 'ok' : (mainForce.pressure === 'bearish' ? 'error' : 'idle')" style="margin:0;width:4px;height:4px;"></span> {{ mainForce.pressure_cn || '均衡' }}</span></div>
                <div class="mf-summary-sm">
                  <div class="mf-bar-sm">
                    <div class="mf-bar-buy-sm" :style="{width: mainForce.pressure_score + '%'}"></div>
                    <div class="mf-bar-sell-sm" :style="{width: (100 - mainForce.pressure_score) + '%'}"></div>
                  </div>
                </div>
                <div class="mf-stats-sm">
                  <div class="mf-stat-sm"><div class="mf-stat-label-sm">大单占比</div><div class="mf-stat-value-sm">{{ mainForce.big_order_ratio || 0 }}%</div></div>
                  <div class="mf-stat-sm"><div class="mf-stat-label-sm">主力净流入</div><div class="mf-stat-value-sm text-profit">${{ formatBig(mainForce.net_inflow || 0) }}</div></div>
                </div>
              </template>
              <!-- 支撑阻力位 -->
              <template v-else-if="item.i === 'supportres'">
                <div class="info-title-sm"><span class="status-light ok" style="margin:0;"></span>支撑阻力位</div>
                <div class="sr-grid-sm">
                  <div class="sr-column-sm">
                    <div class="sr-label-sm">阻力</div>
                    <div v-for="(r, i) in supportResistance.resistances.slice(0, 3)" :key="'r'+i" class="sr-level-sm resistance">
                      <span class="sr-price-sm">{{ r }}</span>
                    </div>
                  </div>
                  <div class="sr-column-sm">
                    <div class="sr-label-sm">枢轴</div>
                    <div v-for="(p, i) in supportResistance.pivot_points.slice(0, 2)" :key="'p'+i" class="pivot-level-sm" :class="p.level">
                      <span class="pivot-price-sm">{{ p.price }}</span>
                    </div>
                  </div>
                  <div class="sr-column-sm">
                    <div class="sr-label-sm">支撑</div>
                    <div v-for="(s, i) in supportResistance.supports.slice(0, 3)" :key="'s'+i" class="sr-level-sm support">
                      <span class="sr-price-sm">{{ s }}</span>
                    </div>
                  </div>
                </div>
              </template>
              <!-- 涨跌参数 -->
              <template v-else-if="item.i === 'risefall'">
                <div class="info-title-sm">涨跌参数</div>
                <div class="rf-grid-sm">
                  <div class="rf-item-sm"><div class="rf-label-sm"><span class="status-light" :class="riseFallParams.change_pct >= 0 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span> 涨跌幅</div><div class="rf-value-sm" :class="riseFallParams.change_pct >= 0 ? 'profit' : 'loss'">{{ riseFallParams.change_pct >= 0 ? '+' : '' }}{{ riseFallParams.change_pct || '0' }}%</div></div>
                  <div class="rf-item-sm"><div class="rf-label-sm"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> 振幅</div><div class="rf-value-sm">{{ riseFallParams.amplitude || '0' }}%</div></div>
                  <div class="rf-item-sm"><div class="rf-label-sm"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> ATR</div><div class="rf-value-sm">{{ riseFallParams.atr_14 || '0' }}</div></div>
                  <div class="rf-item-sm"><div class="rf-label-sm"><span class="status-light warn" style="margin:0;width:4px;height:4px;"></span> 波动率</div><div class="rf-value-sm">{{ riseFallParams.volatility || '0' }}%</div></div>
                  <div class="rf-item-sm"><div class="rf-label-sm"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> 量比</div><div class="rf-value-sm">{{ riseFallParams.vol_ratio || '0' }}</div></div>
                </div>
              </template>
              <!-- 持仓量 & 资金 -->
              <template v-else-if="item.i === 'openinterest'">
                <div class="side-title-sm">持仓 &amp; 资金</div>
                <div class="oi-stats-sm">
                  <div class="oi-item-sm"><span class="oi-label-sm"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> 持仓价值</span><span class="oi-value-sm">${{ formatBig(openInterest.open_interest_usdt) }}</span></div>
                  <div class="oi-item-sm"><span class="oi-label-sm"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> 24h最高</span><span class="oi-value-sm profit">{{ fmtMoney(ticker.high_24h) }}</span></div>
                  <div class="oi-item-sm"><span class="oi-label-sm"><span class="status-light warn" style="margin:0;width:4px;height:4px;"></span> 24h最低</span><span class="oi-value-sm loss">{{ fmtMoney(ticker.low_24h) }}</span></div>
                  <div class="oi-item-sm"><span class="oi-label-sm"><span class="status-light" :class="ticker.change_pct_24h >= 0 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span> 24h涨跌</span><span class="oi-value-sm" :class="ticker.change_pct_24h >= 0 ? 'profit' : 'loss'">{{ ticker.change_pct_24h >= 0 ? '+' : '' }}{{ ticker.change_pct_24h }}%</span></div>
                </div>
              </template>
              <!-- 预警记录 -->
              <template v-else-if="item.i === 'alerts'">
                <div class="side-title-sm"><span class="status-light ok" style="margin:0;"></span>预警记录</div>
                <div class="alert-list-sm">
                  <div v-for="(a, i) in whaleAlerts.slice(0, 6)" :key="i" class="alert-item-sm" :class="a.side === 1 ? 'buy' : 'sell'">
                    <span class="status-light" :class="a.side === 1 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span>
                    <span class="alert-arrow-sm">{{ a.side === 1 ? '&#9650;' : '&#9660;' }}</span>
                    <span class="alert-sym-sm">{{ a.symbol }}</span>
                    <span class="alert-price-sm">{{ fmtMoney(a.price, 2) }}</span>
                  </div>
                  <div v-if="whaleAlerts.length === 0" class="mf-empty-sm">暂无预警</div>
                </div>
              </template>
              <!-- 当前持仓 -->
              <template v-else-if="item.i === 'mypositions'">
                <div class="mp-sm-header">
                  <span class="mp-sm-title">当前持仓</span>
                  <el-tag size="small" type="info" effect="dark" round>{{ myPositions.length }}个</el-tag>
                  <span class="mp-sm-pnl" :class="totalUnrealizedPnl >= 0 ? 'profit' : 'loss'">
                    <span class="status-light" :class="totalUnrealizedPnl >= 0 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span>
                    {{ totalUnrealizedPnl >= 0 ? '+' : '' }}${{ formatBig(totalUnrealizedPnl) }}
                  </span>
                </div>
                <div class="mp-sm-list" v-if="myPositions.length > 0">
                  <div v-for="pos in myPositions" :key="pos.id" class="mp-sm-item" :class="[pos.side === 1 ? 'long' : 'short', { closed: pos.status === 2 }]" @click="focusPosition(pos)">
                    <div class="mp-sm-sym" style="display:flex;align-items:center;gap:2px;">
                      <span class="status-light" :class="pos.side === 1 ? 'ok' : 'error'" style="margin:0;width:4px;height:4px;"></span>
                      {{ pos.symbol }}
                      <el-tag size="small" effect="dark" :type="pos.status === 1 ? 'success' : 'info'">{{ pos.status === 1 ? '持仓中' : '已平仓' }}</el-tag>
                      <el-tag size="small" effect="dark" :type="pos.side === 1 ? 'success' : 'danger'">{{ pos.side === 1 ? '多' : '空' }}{{ pos.leverage }}x</el-tag>
                    </div>
                    <div class="mp-sm-grid">
                      <div class="mp-sm-row"><span class="mp-sm-lbl">数量</span><span class="mp-sm-val">{{ pos.quantity }}</span></div>
                      <div class="mp-sm-row"><span class="mp-sm-lbl">名义值</span><span class="mp-sm-val">${{ formatBig(pos.quantity_usdt) }}</span></div>
                      <div class="mp-sm-row"><span class="mp-sm-lbl">开仓价</span><span class="mp-sm-val">${{ fmtMoney(pos.entry_price) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.status === 1"><span class="mp-sm-lbl">标记价</span><span class="mp-sm-val">${{ fmtMoney(pos.mark_price) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.status === 2 && pos.close_price > 0"><span class="mp-sm-lbl">平仓价</span><span class="mp-sm-val">${{ fmtMoney(pos.close_price) }}</span></div>
                      <div class="mp-sm-row"><span class="mp-sm-lbl">保证金</span><span class="mp-sm-val"><span class="status-light ok" style="margin:0;width:3px;height:3px;"></span> ${{ formatBig(pos.margin) }}</span></div>
                      <div class="mp-sm-row"><span class="mp-sm-lbl">{{ pos.status === 1 ? '盈亏' : '已实现' }}</span><span class="mp-sm-val" :class="(pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) >= 0 ? 'profit' : 'loss'">{{ (pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) >= 0 ? '+' : '' }}${{ formatBig(pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.tp > 0"><span class="mp-sm-lbl">止盈</span><span class="mp-sm-val profit"><span class="status-light ok" style="margin:0;width:3px;height:3px;"></span> ${{ fmtMoney(pos.tp) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.sl > 0"><span class="mp-sm-lbl">止损</span><span class="mp-sm-val loss"><span class="status-light error" style="margin:0;width:3px;height:3px;"></span> ${{ fmtMoney(pos.sl) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.max_drawdown_ratio > 0"><span class="mp-sm-lbl">回撤</span><span class="mp-sm-val"><span class="status-light" :class="pos.max_drawdown_ratio > 2 ? 'error' : 'warn'" style="margin:0;width:3px;height:3px;"></span> {{ pos.max_drawdown_ratio?.toFixed(2) }}%</span></div>
                      <div class="mp-sm-row" v-if="pos.fee_total > 0"><span class="mp-sm-lbl">手续费</span><span class="mp-sm-val">${{ formatBig(pos.fee_total) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.entry_score > 0"><span class="mp-sm-lbl">评分</span><span class="mp-sm-val"><span class="status-light" :class="pos.entry_score >= 7 ? 'ok' : (pos.entry_score >= 5 ? 'warn' : 'idle')" style="margin:0;width:3px;height:3px;"></span> {{ pos.entry_score?.toFixed(1) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.open_time"><span class="mp-sm-lbl">开仓</span><span class="mp-sm-val" style="font-size:10px;">{{ formatPosTime(pos.open_time) }}</span></div>
                      <div class="mp-sm-row" v-if="pos.holding_minutes > 0"><span class="mp-sm-lbl">时长</span><span class="mp-sm-val" style="font-size:10px;">{{ formatHolding(pos.holding_minutes) }}</span></div>
                    </div>
                    <div class="mp-sm-actions" v-if="pos.status === 1" @click.stop>
                      <el-button size="small" type="danger" plain :loading="pos._closing" @click="closePosition(pos)" style="width:100%;font-size:10px;height:22px;padding:0;">
                        <span class="status-light error" style="margin:0;width:3px;height:3px;"></span>
                        市价平仓
                      </el-button>
                    </div>
                  </div>
                </div>
                <div v-else class="mf-empty-sm">暂无持仓</div>
              </template>
            </div>
            <!-- 右下角缩放手柄 -->
            <div v-if="layoutEditMode" class="resize-handle" @mousedown="startResize($event, item.i)" title="拖拽缩放"></div>
          </div>
        </div>
      </div>
    </div>

    <!-- 底部持仓面板（内联，页面可滚动） -->
    <div class="pos-bottom-panel" :class="{ 'pos-bottom-collapsed': posPanelCollapsed }">
      <div class="pos-bottom-header">
        <div class="kpb-title">
          <span class="kpb-icon">💼</span>
          <span>当前持仓</span>
          <el-tag size="small" type="info" effect="dark" round>{{ myPositions.length }}个</el-tag>
        </div>
        <div class="kpb-summary">
          <span class="kpb-summary-item">
            <span class="status-light" :class="totalUnrealizedPnl >= 0 ? 'ok' : 'error'" style="margin:0;width:5px;height:5px;"></span>
            <span class="kpb-sv" :class="totalUnrealizedPnl >= 0 ? 'profit' : 'loss'">
              {{ totalUnrealizedPnl >= 0 ? '+' : '' }}${{ formatBig(totalUnrealizedPnl) }}
            </span>
          </span>
          <span class="pos-bottom-actions">
            <el-icon :size="14" :class="{ 'rotating': positionsLoading }" @click.stop="loadMyPositions" title="刷新"><Refresh /></el-icon>
            <el-icon :size="14" @click.stop="posPanelCollapsed = !posPanelCollapsed" :title="posPanelCollapsed ? '展开' : '折叠'">
              <ArrowDown v-if="!posPanelCollapsed" />
              <Edit v-else />
            </el-icon>
          </span>
        </div>
      </div>
      <div class="pos-bottom-body" v-show="!posPanelCollapsed">
        <div class="kpb-body" v-if="myPositions.length > 0">
          <div v-for="pos in myPositions" :key="pos.id" class="pos-card" :class="[pos.side === 1 ? 'long' : 'short', { closed: pos.status === 2 }]" @click="focusPosition(pos)">
            <div class="pos-card-header">
              <span class="pos-symbol" style="display:flex;align-items:center;gap:4px;">
                <span class="status-light" :class="pos.side === 1 ? 'ok' : 'error'" style="margin:0;"></span>
                {{ pos.symbol }}
              </span>
              <div style="display:flex;gap:4px;align-items:center;">
                <el-tag size="small" effect="dark" :type="pos.status === 1 ? 'success' : 'info'">
                  {{ pos.status === 1 ? '持仓中' : '已平仓' }}
                </el-tag>
                <el-tag size="small" effect="dark" :type="pos.side === 1 ? 'success' : 'danger'">
                  {{ pos.side === 1 ? '多' : '空' }} {{ pos.leverage }}x
                </el-tag>
              </div>
            </div>
            <div class="pos-card-main">
              <div class="pos-row"><span class="pos-label">数量</span><span class="pos-value">{{ pos.quantity }}</span></div>
              <div class="pos-row"><span class="pos-label">名义价值</span><span class="pos-value">${{ formatBig(pos.quantity_usdt) }}</span></div>
              <div class="pos-row"><span class="pos-label">开仓价</span><span class="pos-value">${{ fmtMoney(pos.entry_price) }}</span></div>
              <div class="pos-row"><span class="pos-label">标记价</span><span class="pos-value">${{ fmtMoney(pos.mark_price) }}</span></div>
              <div class="pos-row"><span class="pos-label">保证金</span><span class="pos-value"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> ${{ formatBig(pos.margin) }}</span></div>
              <div class="pos-row pos-pnl-row">
                <span class="pos-label">{{ pos.status === 1 ? '未实现盈亏' : '已实现盈亏' }}</span>
                <span class="pos-value" :class="(pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) >= 0 ? 'profit' : 'loss'">
                  {{ (pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) >= 0 ? '+' : '' }}${{ formatBig(pos.status === 1 ? pos.unrealized_pnl : pos.realized_pnl) }}
                  <span class="pos-pnl-pct" v-if="pos.status === 1">({{ pos.pnl_pct >= 0 ? '+' : '' }}{{ pos.pnl_pct?.toFixed(2) }}%)</span>
                </span>
              </div>
              <div class="pos-row" v-if="pos.status === 2 && pos.close_price > 0"><span class="pos-label">平仓价</span><span class="pos-value">${{ fmtMoney(pos.close_price) }}</span></div>
              <div class="pos-row" v-if="pos.tp > 0"><span class="pos-label">止盈价</span><span class="pos-value profit"><span class="status-light ok" style="margin:0;width:4px;height:4px;"></span> ${{ fmtMoney(pos.tp) }}</span></div>
              <div class="pos-row" v-if="pos.sl > 0"><span class="pos-label">止损价</span><span class="pos-value loss"><span class="status-light error" style="margin:0;width:4px;height:4px;"></span> ${{ fmtMoney(pos.sl) }}</span></div>
              <div class="pos-row" v-if="pos.max_drawdown_ratio > 0"><span class="pos-label">最大回撤</span><span class="pos-value" :class="pos.max_drawdown_ratio > 2 ? 'loss' : ''"><span class="status-light" :class="pos.max_drawdown_ratio > 2 ? 'error' : 'warn'" style="margin:0;width:4px;height:4px;"></span> {{ pos.max_drawdown_ratio?.toFixed(2) }}%</span></div>
              <div class="pos-row" v-if="pos.fee_total > 0"><span class="pos-label">手续费</span><span class="pos-value">${{ formatBig(pos.fee_total) }}</span></div>
              <div class="pos-row" v-if="pos.entry_score > 0"><span class="pos-label">开仓评分</span><span class="pos-value"><span class="status-light" :class="pos.entry_score >= 7 ? 'ok' : (pos.entry_score >= 5 ? 'warn' : 'idle')" style="margin:0;width:4px;height:4px;"></span> {{ pos.entry_score?.toFixed(1) }}</span></div>
              <div class="pos-row" v-if="pos.open_time"><span class="pos-label">开仓时间</span><span class="pos-value" style="font-size:11px;">{{ formatPosTime(pos.open_time) }}</span></div>
              <div class="pos-row" v-if="pos.holding_minutes > 0"><span class="pos-label">持仓时长</span><span class="pos-value" style="font-size:11px;">{{ formatHolding(pos.holding_minutes) }}</span></div>
            </div>
            <div class="pos-card-liquidation" v-if="pos.liquidation_price > 0">
              <span class="pos-liq-label">强平价</span>
              <span class="pos-liq-value"><span class="status-light error" style="margin:0;width:4px;height:4px;"></span> ${{ fmtMoney(pos.liquidation_price) }}</span>
              <div class="pos-liq-bar"><div class="pos-liq-fill" :style="{ width: liqDistancePct(pos) + '%' }"></div></div>
            </div>
            <div class="pos-card-actions" v-if="pos.status === 1" @click.stop>
              <el-button
                size="small"
                type="danger"
                plain
                :loading="pos._closing"
                @click="closePosition(pos)"
                class="pos-close-btn"
              >
                <span class="status-light error" style="margin:0;width:4px;height:4px;"></span>
                市价平仓
              </el-button>
            </div>
          </div>
        </div>
        <div class="kpb-empty" v-else><el-empty description="暂无持仓" :image-size="60" /></div>
      </div>
    </div>

    <!-- 保存布局对话框 -->
    <el-dialog v-model="saveLayoutDialogVisible" :title="saveLayoutIsPublic ? '发布为公共布局' : '保存为我的布局'" width="460px">
      <el-form :model="saveLayoutForm" label-width="90px">
        <el-form-item label="布局名称" required>
          <el-input v-model="saveLayoutForm.name" placeholder="给这个布局起个名字" maxlength="50" show-word-limit />
        </el-form-item>
        <el-form-item label="布局说明">
          <el-input v-model="saveLayoutForm.description" type="textarea" :rows="2" placeholder="可选：描述这个布局的特点或用途" maxlength="200" show-word-limit />
        </el-form-item>
        <el-form-item v-if="saveLayoutIsPublic && userRole === 'admin'" label="设为默认">
          <el-switch v-model="saveLayoutForm.is_default" />
          <div style="font-size:12px;color:#94A3B8;margin-top:4px;">设为默认后，新用户首次进入自定义布局将加载此布局</div>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="saveLayoutDialogVisible = false">取消</el-button>
        <el-button type="primary" :loading="savingLayout" @click="confirmSaveLayout">保存</el-button>
      </template>
    </el-dialog>

    <!-- 大单预警提醒条 -->
    <transition name="slide-down">
      <div v-if="alertDialogVisible" class="whale-alert-bar" :class="latestAlert?.side === 1 ? 'buy' : 'sell'">
        <div class="alert-bar-icon">{{ latestAlert?.side === 1 ? '📈' : '📉' }}</div>
        <div class="alert-bar-info">
          <div class="alert-bar-title">
            <span class="alert-bar-tag">{{ latestAlert?.side === 1 ? '大单买入' : '大单卖出' }}</span>
            {{ selectedSymbol }}
          </div>
          <div class="alert-bar-detail">
            <span class="alert-bar-price">{{ fmtMoney(latestAlert?.price, 4) }}</span>
            <span class="alert-bar-amount">${{ formatBig(latestAlert?.quote_qty) }}</span>
            <span class="alert-bar-time">{{ formatTime(latestAlert?.timestamp_ms) }}</span>
          </div>
        </div>
        <el-icon class="alert-bar-close" @click="alertDialogVisible = false"><Close /></el-icon>
      </div>
    </transition>

    <!-- AI信号预警弹窗 -->
    <el-dialog v-model="aiSignalDialogVisible" title="🤖 AI交易信号预警" width="450px" :close-on-click-modal="false" class="ai-signal-dialog">
      <div class="ai-dialog-content">
        <div class="ai-dialog-icon" :class="latestAISignal?.direction">
          {{ latestAISignal?.direction === 'long' ? '🚀' : latestAISignal?.direction === 'short' ? '📉' : '⏸️' }}
        </div>
        <div class="ai-dialog-title">
          <span class="ai-sym">{{ latestAISignal?.symbol }}</span>
          <span class="ai-direction" :class="latestAISignal?.direction">
            {{ latestAISignal?.direction === 'long' ? '建议买入' : latestAISignal?.direction === 'short' ? '建议卖出' : '观望' }}
          </span>
        </div>
        <div class="ai-dialog-score">
          综合评分: <span :class="latestAISignal?.direction">{{ latestAISignal?.score }}分</span>
        </div>
        <div class="ai-dialog-timeframe">周期: {{ latestAISignal?.timeframe }}</div>
        <div class="ai-dialog-reason" v-if="latestAISignal?.reason">
          <div class="reason-label">AI分析理由</div>
          <div class="reason-text">{{ latestAISignal?.reason }}</div>
        </div>
        <div class="ai-dialog-time">{{ formatTime(latestAISignal?.timestamp_ms) }}</div>
      </div>
      <template #footer>
        <el-button @click="aiSignalDialogVisible = false">知道了</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted, onBeforeUnmount, computed, watch, nextTick, markRaw } from 'vue'
import { useRoute } from 'vue-router'
import * as echarts from 'echarts'
import { Bell, Cpu, Warning, Close, Grid, ArrowDown, Edit, RefreshLeft, Setting, Upload } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { SYMBOL_META, EXCHANGE_META, fmtMoney, fmtPct } from '@/utils/env'
import { http, API_PREFIX } from '@/utils/request'
import { Refresh } from '@element-plus/icons-vue'
import { useUserStore } from '@/store/user'

const userStore = useUserStore()
const route = useRoute()
const isAdmin = computed(() => userStore.isAdmin)

// 按用户区分的本地存储 key，避免不同用户布局串用
const userStorageKey = (key) => {
  const uid = userStore.userInfo?.id || 'guest'
  return `kline_${key}_u${uid}`
}

const selectedSymbol = ref('BTC')
const symbolKeys = computed(() => Object.keys(SYMBOL_META))
const timeframe = ref('1h')
const selectedAccount = ref(0)
const accounts = ref([])
const activeIndicator = ref('ma')

// 布局模式
const layoutMode = ref('classic')
const setLayout = (mode) => {
  layoutMode.value = mode
  localStorage.setItem(userStorageKey('layout'), mode)
  nextTick(() => {
    mainChart?.resize()
    macdChart?.resize()
    rsiChart?.resize()
  })
}

// -------- 底部持仓面板 --------
const posPanelCollapsed = ref(false)

// 加载用户布局配置（确保用户信息已就绪后再读取）
function loadUserLayout() {
  const savedMode = localStorage.getItem(userStorageKey('layout'))
  if (savedMode) {
    layoutMode.value = savedMode
  }
  const savedLayout = localStorage.getItem(userStorageKey('custom_layout'))
  if (savedLayout) {
    try {
      const parsed = JSON.parse(savedLayout)
      if (Array.isArray(parsed) && parsed.find(item => item.i === 'kline-main')) {
        gridLayout.value = parsed
      }
    } catch (e) {}
  }
}

// ===== 自定义可拖拽布局 =====
const layoutEditMode = ref(false)
const gridCols = 12
const gridRowHeight = 40
const gridMargin = 8
const customLayoutRef = ref(null)

// 默认布局配置
const defaultLayout = [
  { i: 'toolbar',       x: 0, y: 0, w: 12, h: 3, minW: 6, minH: 2 },
  { i: 'kline-main',    x: 0, y: 3, w: 12, h: 10, minW: 4, minH: 5 },
  { i: 'macd',          x: 0, y: 13, w: 6, h: 4, minW: 2, minH: 2 },
  { i: 'rsi',           x: 6, y: 13, w: 6, h: 4, minW: 2, minH: 2 },
]

// 所有可用面板的完整配置（用于添加面板功能）
const allPanelsConfig = {
  'toolbar':      { w: 12, h: 2, minW: 6, minH: 1, title: '工具栏' },
  'kline-main':   { w: 8, h: 10, minW: 4, minH: 5, title: 'K线主图' },
  'macd':         { w: 4, h: 4, minW: 2, minH: 2, title: 'MACD' },
  'rsi':          { w: 4, h: 4, minW: 2, minH: 2, title: 'RSI(14)' },
  'orderbook':    { w: 4, h: 8, minW: 2, minH: 4, title: '深度盘口' },
  'trades':       { w: 4, h: 6, minW: 2, minH: 3, title: '近期成交' },
  'liqheatmap':   { w: 4, h: 5, minW: 2, minH: 3, title: '清算热力图' },
  'mainforce':    { w: 4, h: 5, minW: 2, minH: 3, title: '主力位置分析' },
  'supportres':   { w: 4, h: 4, minW: 2, minH: 2, title: '支撑阻力位' },
  'risefall':     { w: 4, h: 4, minW: 2, minH: 2, title: '涨跌参数' },
  'openinterest': { w: 4, h: 5, minW: 2, minH: 3, title: '持仓量 & 资金' },
  'alerts':       { w: 4, h: 4, minW: 2, minH: 2, title: '预警记录' },
  'mypositions':  { w: 12, h: 5, minW: 6, minH: 3, title: '当前持仓' },
}

// 自定义布局先使用默认布局，等用户信息就绪后再加载用户保存的布局
const gridLayout = ref(JSON.parse(JSON.stringify(defaultLayout)))

// 拖拽状态
const dragState = reactive({ item: null, startX: 0, startY: 0, startGridX: 0, startGridY: 0 })
const resizeState = reactive({ item: null, startX: 0, startY: 0, startW: 0, startH: 0 })
const gridColWidth = ref(80) // 每列宽度，运行时计算

// 计算网格总高度（所有面板中最低的底部位置 + 底部间距）
const gridTotalHeight = computed(() => {
  if (!gridLayout.value.length) return 600
  let maxBottom = 0
  for (const item of gridLayout.value) {
    const bottom = item.y + item.h
    if (bottom > maxBottom) maxBottom = bottom
  }
  return maxBottom * gridRowHeight + (maxBottom + 1) * gridMargin
})

const calcGridColWidth = () => {
  if (!customLayoutRef.value) return
  const containerWidth = customLayoutRef.value.clientWidth
  gridColWidth.value = (containerWidth - gridMargin * (gridCols + 1)) / gridCols
}

const getItemStyle = (item) => {
  const left = gridMargin + item.x * (gridColWidth.value + gridMargin)
  const top = gridMargin + item.y * (gridRowHeight + gridMargin)
  const width = item.w * gridColWidth.value + (item.w - 1) * gridMargin
  const height = item.h * gridRowHeight + (item.h - 1) * gridMargin
  return {
    left: left + 'px',
    top: top + 'px',
    width: width + 'px',
    height: height + 'px',
  }
}

// 检查碰撞
const checkCollision = (item, newX, newY, newW, newH, skipId) => {
  for (const other of gridLayout.value) {
    if (other.i === skipId) continue
    const ox = other.x, oy = other.y, ow = other.w, oh = other.h
    if (newX < ox + ow && newX + newW > ox && newY < oy + oh && newY + newH > oy) {
      return true
    }
  }
  return false
}

// 开始拖拽
const startDrag = (e, itemId) => {
  if (!layoutEditMode.value) return
  e.preventDefault()
  const item = gridLayout.value.find(i => i.i === itemId)
  if (!item) return
  dragState.item = itemId
  dragState.startX = e.clientX
  dragState.startY = e.clientY
  dragState.startGridX = item.x
  dragState.startGridY = item.y
  document.addEventListener('mousemove', onDragMove)
  document.addEventListener('mouseup', onDragEnd)
}

const onDragMove = (e) => {
  if (!dragState.item) return
  const dx = e.clientX - dragState.startX
  const dy = e.clientY - dragState.startY
  const item = gridLayout.value.find(i => i.i === dragState.item)
  if (!item) return

  const cellW = gridColWidth.value + gridMargin
  const cellH = gridRowHeight + gridMargin
  let newX = Math.round(dragState.startGridX + dx / cellW)
  let newY = Math.round(dragState.startGridY + dy / cellH)

  // 边界检查
  newX = Math.max(0, Math.min(gridCols - item.w, newX))
  newY = Math.max(0, newY)

  // 碰撞检查
  if (!checkCollision(item, newX, newY, item.w, item.h, dragState.item)) {
    item.x = newX
    item.y = newY
  }
}

const onDragEnd = () => {
  dragState.item = null
  document.removeEventListener('mousemove', onDragMove)
  document.removeEventListener('mouseup', onDragEnd)
  resizeCharts()
}

// 开始缩放
const startResize = (e, itemId) => {
  if (!layoutEditMode.value) return
  e.preventDefault()
  e.stopPropagation()
  const item = gridLayout.value.find(i => i.i === itemId)
  if (!item) return
  resizeState.item = itemId
  resizeState.startX = e.clientX
  resizeState.startY = e.clientY
  resizeState.startW = item.w
  resizeState.startH = item.h
  document.addEventListener('mousemove', onResizeMove)
  document.addEventListener('mouseup', onResizeEnd)
}

const onResizeMove = (e) => {
  if (!resizeState.item) return
  const dx = e.clientX - resizeState.startX
  const dy = e.clientY - resizeState.startY
  const item = gridLayout.value.find(i => i.i === resizeState.item)
  if (!item) return

  const cellW = gridColWidth.value + gridMargin
  const cellH = gridRowHeight + gridMargin
  let newW = Math.max(item.minW, Math.round(resizeState.startW + dx / cellW))
  let newH = Math.max(item.minH, Math.round(resizeState.startH + dy / cellH))

  // 边界检查
  newW = Math.min(newW, gridCols - item.x)

  // 碰撞检查
  if (!checkCollision(item, item.x, item.y, newW, newH, resizeState.item)) {
    item.w = newW
    item.h = newH
  }
}

const onResizeEnd = () => {
  resizeState.item = null
  document.removeEventListener('mousemove', onResizeMove)
  document.removeEventListener('mouseup', onResizeEnd)
  resizeCharts()
}

const resizeCharts = () => {
  nextTick(() => {
    mainChart?.resize()
    macdChart?.resize()
    rsiChart?.resize()
  })
}

const toggleEditMode = () => {
  layoutEditMode.value = !layoutEditMode.value
  if (!layoutEditMode.value) {
    localStorage.setItem(userStorageKey('custom_layout'), JSON.stringify(gridLayout.value))
    ElMessage.success('布局已保存')
  }
  nextTick(() => calcGridColWidth())
  resizeCharts()
}

const resetLayout = () => {
  gridLayout.value = JSON.parse(JSON.stringify(defaultLayout))
  localStorage.removeItem(userStorageKey('custom_layout'))
  ElMessage.success('已恢复默认布局')
  nextTick(() => calcGridColWidth())
  resizeCharts()
}

// ---------- 云端布局（个人+公共） ----------
const saveLayoutDialogVisible = ref(false)
const saveLayoutIsPublic = ref(false)
const savingLayout = ref(false)
const publicLayouts = ref([])
const myLayouts = ref([])
const saveLayoutForm = reactive({
  name: '',
  description: '',
  is_default: false,
})

const userRole = computed(() => userStore.userInfo?.role || 'trader')

// 加载云端布局列表
async function loadCloudLayouts() {
  try {
    const [pub, my] = await Promise.all([
      http.get(`${API_PREFIX}/kline-layouts/public`).catch(() => ({ layouts: [] })),
      http.get(`${API_PREFIX}/kline-layouts/my`).catch(() => ({ layouts: [] })),
    ])
    publicLayouts.value = pub.layouts || []
    myLayouts.value = my.layouts || []
  } catch (e) {
    // 静默失败
  }
}

// 云端布局菜单命令
function onCloudLayoutCommand(cmd) {
  if (cmd === 'save-my') {
    saveLayoutIsPublic.value = false
    saveLayoutForm.name = ''
    saveLayoutForm.description = ''
    saveLayoutForm.is_default = false
    saveLayoutDialogVisible.value = true
  } else if (cmd === 'save-public') {
    saveLayoutIsPublic.value = true
    saveLayoutForm.name = ''
    saveLayoutForm.description = ''
    saveLayoutForm.is_default = false
    saveLayoutDialogVisible.value = true
  } else if (cmd.startsWith('load-my:') || cmd.startsWith('load-public:')) {
    const [, idStr] = cmd.split(':')
    const id = parseInt(idStr)
    const layouts = cmd.startsWith('load-my:') ? myLayouts.value : publicLayouts.value
    const layout = layouts.find(l => l.id === id)
    if (layout) {
      applyCloudLayout(layout)
    }
  }
}

// 确认保存布局
async function confirmSaveLayout() {
  if (!saveLayoutForm.name.trim()) {
    ElMessage.warning('请输入布局名称')
    return
  }
  savingLayout.value = true
  try {
    await http.post(`${API_PREFIX}/kline-layouts`, {
      name: saveLayoutForm.name.trim(),
      description: saveLayoutForm.description.trim(),
      layout_data: JSON.stringify(gridLayout.value),
      is_public: saveLayoutIsPublic.value,
    })
    ElMessage.success(saveLayoutIsPublic.value ? '已发布为公共布局' : '布局已保存到云端')
    saveLayoutDialogVisible.value = false
    loadCloudLayouts()
  } catch (e) {
    // 错误已由拦截器提示
  } finally {
    savingLayout.value = false
  }
}

// 应用云端布局
async function applyCloudLayout(layout) {
  try {
    let data = layout.layout_data
    if (typeof data === 'string') {
      data = JSON.parse(data)
    }
    if (Array.isArray(data) && data.length > 0) {
      gridLayout.value = data
      // 保存到本地
      localStorage.setItem(userStorageKey('custom_layout'), JSON.stringify(data))
      nextTick(() => {
        calcGridColWidth()
        resizeCharts()
      })
      ElMessage.success(`已应用布局「${layout.name}」`)
      // 增加使用计数
      try {
        http.post(`${API_PREFIX}/kline-layouts/${layout.id}/apply`)
      } catch (e) {}
    } else {
      ElMessage.error('布局数据格式错误')
    }
  } catch (e) {
    ElMessage.error('加载布局失败')
  }
}

// 悬浮按钮命令处理
const onFabCommand = (cmd) => {
  if (cmd === 'resetLayout') {
    resetLayout()
  } else if (cmd === 'startEdit' || cmd === 'finishEdit') {
    toggleEditMode()
  } else {
    setLayout(cmd)
  }
}

// 计算未使用的面板列表
const availablePanels = computed(() => {
  const used = new Set(gridLayout.value.map(item => item.i))
  return Object.keys(allPanelsConfig).filter(key => !used.has(key))
})

// 添加面板
const addPanel = (panelId) => {
  const cfg = allPanelsConfig[panelId]
  if (!cfg) return
  // 找到最底部的位置放新面板
  let maxY = 0
  for (const item of gridLayout.value) {
    const bottom = item.y + item.h
    if (bottom > maxY) maxY = bottom
  }
  gridLayout.value.push({
    i: panelId,
    x: 0,
    y: maxY + 1,
    w: cfg.w,
    h: cfg.h,
    minW: cfg.minW,
    minH: cfg.minH,
  })
  ElMessage.success(`已添加「${cfg.title}」`)
  nextTick(() => calcGridColWidth())
  resizeCharts()
}

// 删除面板
const removePanel = (panelId) => {
  if (panelId === 'kline-main' || panelId === 'toolbar') {
    ElMessage.warning('工具栏和K线主图不能删除')
    return
  }
  const idx = gridLayout.value.findIndex(item => item.i === panelId)
  if (idx >= 0) {
    const title = panelTitles[panelId] || panelId
    gridLayout.value.splice(idx, 1)
    ElMessage.info(`已移除「${title}」，编辑完成后保存生效`)
    nextTick(() => calcGridColWidth())
    resizeCharts()
  }
}

// 面板组件映射
const panelTitles = {
  'toolbar': '工具栏',
  'kline-main': 'K线主图',
  'macd': 'MACD',
  'rsi': 'RSI(14)',
  'orderbook': '深度盘口',
  'trades': '近期成交',
  'liqheatmap': '清算热力图',
  'mainforce': '主力位置分析',
  'supportres': '支撑阻力位',
  'risefall': '涨跌参数',
  'openinterest': '持仓量 & 资金',
  'alerts': '预警记录',
  'mypositions': '当前持仓',
}

// 数据
const klines = ref([])
const klineError = ref('')
const connStatus = ref('ok')  // ok / error / loading
const connLastUpdate = ref(0)  // timestamp of last successful update
let connErrorCount = 0
const indicators = ref({})
const supportResistance = ref({ supports: [], resistances: [], pivot_points: [] })
const trend = ref({ short_term: 'neutral', mid_term: 'neutral', rsi: 50, last_price: 0 })
const multiPeriod = ref({})
const riseFallParams = ref({})
const liqHeatmap = ref({ long_liq: [], short_liq: [], danger_levels: [], heatmap: [] })
const mainForce = ref({ walls: [], pressure: 'neutral', pressure_cn: '多空均衡', pressure_score: 50, big_order_ratio: 0 })
const orderbook = ref({ bids: [], asks: [] })
const recentTrades = ref([])
const openInterest = ref({ open_interest: 0, open_interest_usdt: 0 })
const ticker = ref({ last_price: 0, high_24h: 0, low_24h: 0, volume_24h: 0, change_pct_24h: 0 })

// 预警
const whaleAlerts = ref([])
const whaleThreshold = ref(50000)
const popupAlertEnabled = ref(true)
const emailAlertEnabled = ref(true)
const alertDialogVisible = ref(false)
const latestAlert = ref(null)

// 大单成交统计
const bigTradeStats = computed(() => {
  let buyCount = 0, sellCount = 0
  let buyAmount = 0, sellAmount = 0
  for (const t of recentTrades.value) {
    if (t.quote_qty >= whaleThreshold.value) {
      if (t.side === 1) { buyCount++; buyAmount += t.quote_qty }
      else { sellCount++; sellAmount += t.quote_qty }
    }
  }
  return { buyCount, sellCount, buyAmount, sellAmount }
})

// AI信号预警
const aiSignalEnabled = ref(false)
const aiSignalThreshold = ref(6)
const aiAnalyzing = ref(false)
const aiSignalDialogVisible = ref(false)
const latestAISignal = ref(null)

// 预警币种配置（从localStorage加载）
const ALERT_STORAGE_KEY = 'kline_alert_config'
const alertSymbols = ref({})
function initAlertSymbols() {
  try {
    const saved = localStorage.getItem(ALERT_STORAGE_KEY)
    if (saved) {
      const cfg = JSON.parse(saved)
      alertSymbols.value = cfg.symbols || {}
      whaleThreshold.value = cfg.threshold || 50000
      popupAlertEnabled.value = cfg.popup !== false
      emailAlertEnabled.value = cfg.email !== false
      aiSignalEnabled.value = cfg.ai_enabled === true
      aiSignalThreshold.value = cfg.ai_threshold || 6
    } else {
      // 默认只开启 BTC 和 ETH
      for (const k of Object.keys(SYMBOL_META)) {
        alertSymbols.value[k] = (k === 'BTC' || k === 'ETH')
      }
    }
  } catch (e) {
    for (const k of Object.keys(SYMBOL_META)) {
      alertSymbols.value[k] = (k === 'BTC' || k === 'ETH')
    }
  }
}
function saveAlertConfig() {
  try {
    localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify({
      symbols: alertSymbols.value,
      threshold: whaleThreshold.value,
      popup: popupAlertEnabled.value,
      email: emailAlertEnabled.value,
      ai_enabled: aiSignalEnabled.value,
      ai_threshold: aiSignalThreshold.value,
    }))
  } catch (e) {}
}
function selectAllSymbols() {
  for (const k of Object.keys(SYMBOL_META)) {
    alertSymbols.value[k] = true
  }
  saveAlertConfig()
}
// 监听配置变化，自动保存
watch([alertSymbols, whaleThreshold, popupAlertEnabled, emailAlertEnabled, aiSignalEnabled, aiSignalThreshold], () => {
  saveAlertConfig()
}, { deep: true })

// 图表
const mainChartRef = ref(null)
const macdChartRef = ref(null)
const rsiChartRef = ref(null)
let mainChart = null
let macdChart = null
let rsiChart = null

// 定时器
let refreshTimer = null
let klineTimer = null
let tickerTimer = null
let priceDirection = ref('neutral')
let lastPrice = 0

// 计算
const spread = computed(() => {
  if (!orderbook.value.bids.length || !orderbook.value.asks.length) return 0
  return orderbook.value.asks[0].price - orderbook.value.bids[0].price
})
const spreadPct = computed(() => {
  if (!ticker.value.last_price) return '0.00'
  return ((spread.value / ticker.value.last_price) * 100).toFixed(3)
})

function trendText(t) {
  return { up: '上涨', down: '下跌', neutral: '震荡' }[t] || '震荡'
}
function periodLabel(k) {
  return { '1d': '1天', '1w': '1周', '1m': '1月', '2m': '2月', '3m': '3月', '6m': '6月', '1y': '1年' }[k] || k
}
function formatBig(v) {
  if (!v && v !== 0) return '0'
  const num = Number(v)
  if (isNaN(num)) return '0'
  if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B'
  if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M'
  if (num >= 1e3) return (num / 1e3).toFixed(2) + 'K'
  return num.toFixed(2)
}
function formatTime(ms) {
  if (!ms) return '--'
  const d = new Date(ms)
  const h = String(d.getHours()).padStart(2, '0')
  const m = String(d.getMinutes()).padStart(2, '0')
  const s = String(d.getSeconds()).padStart(2, '0')
  return `${h}:${m}:${s}`
}
function getObPct(total, side) {
  const max = Math.max(
    ...orderbook.value.bids.map(b => b.total),
    ...orderbook.value.asks.map(a => a.total),
    1
  )
  return (total / max) * 100
}

