// 计算主力位置（前端计算，基于盘口数据）
function calcMainForce() {
  const bids = orderbook.value.bids || []
  const asks = orderbook.value.asks || []
  if (!bids.length || !asks.length) {
    mainForce.value = { walls: [], pressure: 'neutral', pressure_cn: '多空均衡', pressure_score: 50, big_order_ratio: 0 }
    return
  }
  const bidQtys = bids.map(b => b.quantity)
  const askQtys = asks.map(a => a.quantity)
  const avgBid = bidQtys.reduce((s, v) => s + v, 0) / bidQtys.length
  const avgAsk = askQtys.reduce((s, v) => s + v, 0) / askQtys.length

  const walls = []
  for (const b of bids) {
    if (b.quantity > avgBid * 2) {
      walls.push({ price: b.price, quantity: b.quantity, side: 'buy', side_cn: '买盘支撑',
        strength: Math.round(b.quantity / avgBid * 10) / 10 })
    }
  }
  for (const a of asks) {
    if (a.quantity > avgAsk * 2) {
      walls.push({ price: a.price, quantity: a.quantity, side: 'sell', side_cn: '卖盘压单',
        strength: Math.round(a.quantity / avgAsk * 10) / 10 })
    }
  }
  walls.sort((a, b) => b.quantity - a.quantity)

  const totalBid = bids.reduce((s, b) => s + (b.total || 0), 0)
  const totalAsk = asks.reduce((s, a) => s + (a.total || 0), 0)
  const buyRatio = totalBid / (totalBid + totalAsk) * 100 || 50

  let pressure = 'neutral', pressure_cn = '多空均衡'
  if (buyRatio > 60) { pressure = 'bullish'; pressure_cn = '多头主导' }
  else if (buyRatio < 40) { pressure = 'bearish'; pressure_cn = '空头主导' }

  const bigBidQty = bids.filter(b => b.quantity > avgBid * 1.5).reduce((s, b) => s + b.quantity, 0)
  const bigAskQty = asks.filter(a => a.quantity > avgAsk * 1.5).reduce((s, a) => s + a.quantity, 0)
  const totalQty = bidQtys.reduce((s, v) => s + v, 0) + askQtys.reduce((s, v) => s + v, 0)
  const bigOrderRatio = totalQty > 0 ? Math.round((bigBidQty + bigAskQty) / totalQty * 1000) / 10 : 0

  mainForce.value = {
    walls: walls.slice(0, 6),
    pressure, pressure_cn,
    pressure_score: Math.round(buyRatio * 10) / 10,
    big_order_ratio: bigOrderRatio,
    total_bid_depth: Math.round(totalBid * 100) / 100,
    total_ask_depth: Math.round(totalAsk * 100) / 100,
  }
}

// 加载成交记录
async function loadTrades() {
  try {
    const r = await http.get(`${API_PREFIX}/exchange/trades/${selectedSymbol.value}`, {
      limit: 50,
      account_id: selectedAccount.value,
    }, { _silent: true })
    const newTrades = r.items || []

    // 检测大资金异动
    const prevIds = new Set(recentTrades.value.map(t => t.trade_id))
    const symbolEnabled = alertSymbols.value[selectedSymbol.value] !== false
    for (const t of newTrades) {
      if (!prevIds.has(t.trade_id) && t.quote_qty >= whaleThreshold.value) {
        whaleAlerts.value.unshift({ ...t, symbol: selectedSymbol.value })
        if (whaleAlerts.value.length > 20) whaleAlerts.value.pop()
        // 只有该币种开启了预警才触发
        if (symbolEnabled) {
          // 弹窗提醒
          if (popupAlertEnabled.value) {
            latestAlert.value = t
            alertDialogVisible.value = true
          }
          // 邮件提醒
          if (emailAlertEnabled.value) {
            sendWhaleAlertEmail(t)
          }
        }
      }
    }

    recentTrades.value = newTrades
  } catch (e) {}
}

