// AI分析
async function runAIAnalysis() {
  if (!aiSignalEnabled.value) {
    ElMessage.info('请先开启AI信号提醒')
    return
  }
  aiAnalyzing.value = true
  try {
    const r = await http.post(`${API_PREFIX}/ai/analyze`, {
      analysis_type: 'technical',
      symbol: selectedSymbol.value,
      timeframe: timeframe.value,
      mock: false,
    })
    // 判断是否达到预警阈值
    const score = r.ai_score || 0
    const direction = r.ai_direction || 'neutral'
    const symbolEnabled = alertSymbols.value[selectedSymbol.value] !== false

    if (score >= aiSignalThreshold.value && symbolEnabled && direction !== 'neutral') {
      latestAISignal.value = {
        symbol: selectedSymbol.value,
        direction: direction,
        score: score,
        reason: r.ai_reason || '',
        timeframe: timeframe.value,
        timestamp_ms: Date.now(),
      }
      // 弹窗
      if (popupAlertEnabled.value) {
        aiSignalDialogVisible.value = true
      }
      // 邮件
      if (emailAlertEnabled.value) {
        sendAISignalEmail(latestAISignal.value)
      }
    } else {
      ElMessage.info(`AI分析完成：评分 ${score} 分，未达到预警阈值`)
    }
  } catch (e) {
    ElMessage.error('AI分析失败，请检查AI配置')
  } finally {
    aiAnalyzing.value = false
  }
}

