// ========== ECharts 渲染 ==========

function initCharts() {
  // 兼容普通布局（单个ref）和自定义布局（v-for内的ref数组）
  const getRefEl = (refVal) => {
    if (!refVal) return null
    if (Array.isArray(refVal)) {
      // 过滤掉非元素项，取第一个可用的
      const valid = refVal.filter(v => v && v.nodeType === 1)
      return valid[0] || null
    }
    return refVal
  }

  const mainEl = getRefEl(mainChartRef.value)
  const macdEl = getRefEl(macdChartRef.value)
  const rsiEl = getRefEl(rsiChartRef.value)

  if (mainEl && !mainChart) {
    mainChart = echarts.init(mainEl)
  }
  if (macdEl && !macdChart) {
    macdChart = echarts.init(macdEl)
  }
  if (rsiEl && !rsiChart) {
    rsiChart = echarts.init(rsiEl)
  }
}

// 销毁图表（切换布局时用）
function disposeCharts() {
  mainChart?.dispose()
  macdChart?.dispose()
  rsiChart?.dispose()
  mainChart = null
  macdChart = null
  rsiChart = null
}

// 监听布局模式切换，重建图表
watch(layoutMode, () => {
  disposeCharts()
  nextTick(() => {
    if (layoutMode.value === 'custom') {
      calcGridColWidth()
    }
    initCharts()
    renderCharts()
  })
})

function renderCharts() {
  initCharts()
  renderMainChart()
  renderMacdChart()
  renderRsiChart()
}

function renderMainChart() {
  if (!mainChart || !klines.value.length) return

  const times = klines.value.map(k => new Date(k.t))
  const ohlc = klines.value.map(k => [k.o, k.c, k.l, k.h])
  const volumes = klines.value.map((k, i) => ({
    value: k.v,
    itemStyle: { color: k.c >= k.o ? '#4ADE80' : '#F87171' }
  }))

  const series = [
    {
      name: 'K线',
      type: 'candlestick',
      data: ohlc,
      itemStyle: {
        color: '#4ADE80',
        color0: '#F87171',
        borderColor: '#4ADE80',
        borderColor0: '#F87171',
      },
    },
    {
      name: '成交量',
      type: 'bar',
      xAxisIndex: 1,
      yAxisIndex: 1,
      data: volumes,
    },
  ]

  // 指标线
  const ind = indicators.value
  if (activeIndicator.value === 'ma') {
    if (ind.ma5) series.push({ name: 'MA5', type: 'line', data: ind.ma5, smooth: true, lineStyle: { width: 1, color: '#FBBF24' }, showSymbol: false })
    if (ind.ma10) series.push({ name: 'MA10', type: 'line', data: ind.ma10, smooth: true, lineStyle: { width: 1, color: '#60A5FA' }, showSymbol: false })
    if (ind.ma20) series.push({ name: 'MA20', type: 'line', data: ind.ma20, smooth: true, lineStyle: { width: 1, color: '#A78BFA' }, showSymbol: false })
    if (ind.ma60) series.push({ name: 'MA60', type: 'line', data: ind.ma60, smooth: true, lineStyle: { width: 1, color: '#F97316' }, showSymbol: false })
  } else if (activeIndicator.value === 'boll') {
    if (ind.boll_upper) series.push({ name: 'BOLL上轨', type: 'line', data: ind.boll_upper, smooth: true, lineStyle: { width: 1, color: '#60A5FA' }, showSymbol: false })
    if (ind.boll_mid) series.push({ name: 'BOLL中轨', type: 'line', data: ind.boll_mid, smooth: true, lineStyle: { width: 1, color: '#A78BFA' }, showSymbol: false })
    if (ind.boll_lower) series.push({ name: 'BOLL下轨', type: 'line', data: ind.boll_lower, smooth: true, lineStyle: { width: 1, color: '#60A5FA' }, showSymbol: false })
  }

  // 支撑阻力标记线
  const markLines = []
  if (supportResistance.value.resistances?.length) {
    supportResistance.value.resistances.forEach(r => {
      markLines.push({
        yAxis: r,
        label: { formatter: 'R ' + r, position: 'end', color: '#F87171', fontSize: 10 },
        lineStyle: { color: '#F87171', type: 'dashed', width: 1 },
      })
    })
  }
  if (supportResistance.value.supports?.length) {
    supportResistance.value.supports.forEach(s => {
      markLines.push({
        yAxis: s,
        label: { formatter: 'S ' + s, position: 'end', color: '#4ADE80', fontSize: 10 },
        lineStyle: { color: '#4ADE80', type: 'dashed', width: 1 },
      })
    })
  }
  if (markLines.length && series[0]) {
    series[0].markLine = {
      silent: true,
      symbol: 'none',
      data: markLines,
    }
  }

  const option = {
    backgroundColor: 'transparent',
    animation: false,
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'cross' },
      backgroundColor: 'rgba(15, 23, 42, 0.95)',
      borderColor: '#334155',
      textStyle: { color: '#E2E8F0' },
    },
    axisPointer: { link: [{ xAxisIndex: 'all' }] },
    grid: [
      { left: '8%', right: '3%', top: '5%', height: '60%' },
      { left: '8%', right: '3%', top: '72%', height: '18%' },
    ],
    xAxis: [
      { type: 'category', data: times, gridIndex: 0, axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { color: '#94A3B8' }, splitLine: { show: false } },
      { type: 'category', data: times, gridIndex: 1, axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { show: false }, splitLine: { show: false } },
    ],
    yAxis: [
      { type: 'value', gridIndex: 0, scale: true, position: 'right', axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { color: '#94A3B8' }, splitLine: { lineStyle: { color: '#1E293B' } } },
      { type: 'value', gridIndex: 1, scale: true, position: 'right', axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { color: '#94A3B8', fontSize: 10 }, splitLine: { lineStyle: { color: '#1E293B' } } },
    ],
    dataZoom: [
      { type: 'inside', xAxisIndex: [0, 1], start: 50, end: 100 },
      { type: 'slider', xAxisIndex: [0, 1], start: 50, end: 100, bottom: 0, height: 20, borderColor: '#334155', fillerColor: 'rgba(59, 130, 246, 0.15)' },
    ],
    series,
  }

  mainChart.setOption(option)
}

