    xAxis: { type: 'category', data: times, axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { show: false }, splitLine: { show: false } },
    yAxis: { type: 'value', min: 0, max: 100, position: 'right', axisLine: { lineStyle: { color: '#334155' } }, axisLabel: { color: '#94A3B8', fontSize: 10 }, splitLine: { lineStyle: { color: '#1E293B' } } },
    dataZoom: [{ type: 'inside', start: 50, end: 100 }],
    series: [
      {
        name: 'RSI', type: 'line', data: ind.rsi, smooth: true,
        lineStyle: { width: 1.5, color: '#A78BFA' },
