          silent: true,
          symbol: 'none',
          data: [
            { yAxis: 70, lineStyle: { color: '#F87171', type: 'dashed', width: 1 }, label: { formatter: '超买70', color: '#F87171', fontSize: 10 } },
            { yAxis: 30, lineStyle: { color: '#4ADE80', type: 'dashed', width: 1 }, label: { formatter: '超卖30', color: '#4ADE80', fontSize: 10 } },
            { yAxis: 50, lineStyle: { color: '#64748B', type: 'dotted', width: 1 }, label: { show: false } },
          ],
        },
      },
    ],
  }
  rsiChart.setOption(option)
}

// 窗口大小变化
function onResize() {
  mainChart?.resize()
  macdChart?.resize()
  rsiChart?.resize()
  if (layoutMode.value === 'custom') {
    calcGridColWidth()
  }
}

onMounted(async () => {
  // 从全局搜索跳转时读取品种参数
  const querySymbol = route.query.symbol
  if (querySymbol && SYMBOL_META[querySymbol]) {
    selectedSymbol.value = querySymbol
  }
  // 先加载用户布局配置（确保用户信息已就绪）
  loadUserLayout()
  initAlertSymbols()
  await loadAccounts()
  loadAll()
  loadCloudLayouts()
  window.addEventListener('resize', onResize)
  nextTick(() => calcGridColWidth())

  // 定时刷新（3秒刷新深度和成交，15秒刷新K线和持仓）
  refreshTimer = setInterval(() => {
    loadOrderbook()
    loadTrades()
  }, 3000)

  tickerTimer = setInterval(() => {
    loadTicker()
  }, 1000)

  klineTimer = setInterval(() => {
    loadKlineAnalysis()
    loadOpenInterest()
  }, 15000)
})

onBeforeUnmount(() => {
  window.removeEventListener('resize', onResize)
  if (refreshTimer) clearInterval(refreshTimer)
  if (tickerTimer) clearInterval(tickerTimer)
  if (klineTimer) clearInterval(klineTimer)
  mainChart?.dispose()
  macdChart?.dispose()
  rsiChart?.dispose()
})
</script>

