/* 深度盘口 */
.orderbook {
  font-size: 12px;
  font-family: monospace;

  .ob-header {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    color: #64748B;
    font-size: 11px;
    padding: 4px 0;
    border-bottom: 1px solid #1E293B;
    text-align: right;
    span:first-child { text-align: left; }
  }

  .ob-row {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    padding: 3px 0;
    text-align: right;
    cursor: pointer;
    &:hover { background: rgba(59, 130, 246, 0.1); }

    .ob-price { text-align: left; font-weight: 600; }
    .ask-price { color: #F87171; }
    .bid-price { color: #4ADE80; }

    .ob-bg {
      position: absolute;
      top: 0;
      bottom: 0;
      opacity: 0.15;
    }
    .ask-bg { right: 0; background: #F87171; }
    .bid-bg { right: 0; background: #4ADE80; }
  }

  .ob-asks { display: flex; flex-direction: column-reverse; }

  .ob-spread {
    display: flex;
    justify-content: space-between;
    padding: 8px 0;
    margin: 4px 0;
    border-top: 1px solid #1E293B;
    border-bottom: 1px solid #1E293B;

    .spread-label { color: #64748B; font-size: 11px; }
    .spread-value { color: #FBBF24; font-weight: 700; font-size: 13px; }
  }
}

/* 近期成交 */
.trades-header {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  color: #64748B;
  font-size: 11px;
  padding: 4px 0;
  border-bottom: 1px solid #1E293B;
  font-family: monospace;
  text-align: right;
  span:first-child { text-align: left; }
}
.trades-list {
  max-height: 240px;
  overflow-y: auto;
  font-family: monospace;
  font-size: 12px;
}
.trade-row {
  display: grid;
  grid-template-columns: 1fr 1.3fr 0.8fr;
  padding: 4px 0;
  text-align: right;
  border-bottom: 1px solid rgba(30, 41, 59, 0.5);
  transition: background .15s;

  .trade-price {
    text-align: left;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 4px;
  }
  .trade-arrow { font-size: 10px; }
  .trade-qty {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 2px;
    line-height: 1.2;
  }
  .trade-quote { color: #64748B; font-size: 10px; }
  .trade-time { color: #64748B; font-size: 11px; align-self: center; }
  .big-tag { margin-top: 2px; font-size: 10px; padding: 0 4px; height: 16px; line-height: 16px; }

  &.buy .trade-price { color: #4ADE80; }
  &.buy .trade-arrow { color: #4ADE80; }
  &.sell .trade-price { color: #F87171; }
  &.sell .trade-arrow { color: #F87171; }

  &.is-big {
    background: rgba(251, 191, 36, 0.06);
    border-left: 2px solid #FBBF24;
    padding-left: 6px;
  }
}

/* 大单统计 */
.trades-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 10px;
  padding: 8px;
  background: rgba(15, 23, 42, 0.6);
  border-radius: 6px;
  border: 1px solid #1E293B;
}
.ts-item {
  text-align: center;
  .ts-label { font-size: 11px; color: #94A3B8; margin-bottom: 2px; }
  .ts-value { font-size: 14px; font-weight: 700; }
  .ts-amount { font-size: 11px; color: #64748B; margin-top: 1px; }
  &.buy .ts-value { color: #4ADE80; }
  &.sell .ts-value { color: #F87171; }
}

/* 持仓量信息 */
.oi-info {
  .oi-row {
    display: flex;
    justify-content: space-between;
    padding: 5px 0;
    border-bottom: 1px solid #1E293B;
    font-size: 12px;

    &:last-child { border-bottom: none; }

    .oi-label { color: #94A3B8; }
    .oi-value {
      font-family: monospace;
      font-weight: 600;
      color: #E2E8F0;
      &.high { color: #F87171; }
      &.low { color: #4ADE80; }
      &.profit { color: #4ADE80; }
      &.loss { color: #F87171; }
    }
  }
}

/* 预警卡片 */
.alert-card {
  border-color: #FBBF24;

  .alert-list {
    max-height: 180px;
    overflow-y: auto;
  }
  .alert-empty {
    text-align: center;
    color: #64748B;
    padding: 20px 0;
    font-size: 13px;
    .alert-tip { font-size: 11px; margin-top: 4px; color: #475569; }
  }
  .alert-item {
    padding: 8px;
    margin-bottom: 6px;
    border-radius: 6px;
    border-left: 3px solid;
    background: #0A1118;

    &.buy { border-left-color: #4ADE80; .alert-side { color: #4ADE80; } }
    &.sell { border-left-color: #F87171; .alert-side { color: #F87171; } }

    .alert-side { font-size: 12px; font-weight: 700; margin-bottom: 3px; }
    .alert-price { font-family: monospace; font-size: 13px; color: #E2E8F0; }
    .alert-amount { font-family: monospace; font-size: 12px; color: #FBBF24; margin-top: 2px; }
    .alert-time { font-size: 11px; color: #64748B; margin-top: 2px; }
  }
  .alert-config {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid #1E293B;
    .alert-config-label { font-size: 12px; color: #94A3B8; }
  }
  .alert-symbols {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid #1E293B;
    .alert-symbols-title {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 12px;
      color: #94A3B8;
      margin-bottom: 8px;
    }
    .alert-symbols-list {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 6px;
      :deep(.el-checkbox) {
        font-size: 12px;
        color: #CBD5E1;
        .el-checkbox__label { padding-left: 4px; }
      }
    }
    .alert-symbol-item {
      .sym-icon { margin-right: 2px; }
      .sym-name { font-weight: 600; font-family: monospace; }
    }
  }
}

.whale-alert-bar {
  position: fixed;
  top: 0;
  left: calc(50% - 5cm);
  transform: translateX(-50%);
  z-index: 9999;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 8px 20px;
  background: rgba(17, 28, 42, 0.95);
  border: 1.5px solid #FBBF24;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.4);
  backdrop-filter: blur(6px);
  min-width: 420px;
  max-width: 600px;
  text-align: center;

  &.buy { border-color: #25D07D; }
  &.sell { border-color: #F87171; }

  .alert-bar-icon {
    font-size: 22px;
    line-height: 1;
    flex-shrink: 0;
  }
  .alert-bar-info {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 12px;
  }
  .alert-bar-title {
    font-size: 12px;
    color: #94A3B8;
    white-space: nowrap;
  }
  .alert-bar-tag {
    display: inline-block;
    font-size: 12px;
    padding: 2px 8px;
    border-radius: 4px;
    background: rgba(251, 191, 36, 0.15);
    color: #FBBF24;
    font-weight: 600;
    white-space: nowrap;
  }
  .buy .alert-bar-tag { background: rgba(37, 208, 125, 0.15); color: #25D07D; }
  .sell .alert-bar-tag { background: rgba(248, 113, 113, 0.15); color: #F87171; }

  .alert-bar-detail {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 12px;
    font-size: 12px;
  }
  .alert-bar-price {
    font-family: monospace;
    font-weight: 700;
    color: #F0F4F8;
    font-size: 14px;
    white-space: nowrap;
  }
  .alert-bar-amount {
    color: #FBBF24;
    font-weight: 600;
    font-size: 13px;
    white-space: nowrap;
  }
  .buy .alert-bar-amount { color: #25D07D; }
  .sell .alert-bar-amount { color: #F87171; }

  .alert-bar-time {
    color: #64748B;
    font-size: 11px;
    white-space: nowrap;
  }
  .alert-bar-close {
    position: absolute;
    top: 6px;
    right: 8px;
    cursor: pointer;
    color: #64748B;
    font-size: 14px;
    &:hover { color: #F0F4F8; }
  }
}
.slide-down-enter-active,
.slide-down-leave-active {
  transition: all 0.3s ease;
}
.slide-down-enter-from,
.slide-down-leave-to {
  opacity: 0;
  transform: translateY(-10px);
}

.ai-signal-dialog {
  :deep(.el-dialog) {
    border-radius: 12px;
    background: #111C2A;
    border: 2px solid #818CF8;
  }
  .ai-dialog-content {
    text-align: center;
    padding: 10px 0;
  }
  .ai-dialog-icon {
    font-size: 48px;
    margin-bottom: 12px;
    animation: pulse 1s infinite;
  }
  .ai-dialog-title {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 12px;
    .ai-sym { font-size: 20px; font-weight: 800; font-family: monospace; color: #E2E8F0; }
    .ai-direction {
      font-size: 18px;
      font-weight: 700;
      padding: 4px 12px;
      border-radius: 6px;
      &.long { background: #052E1B; color: #4ADE80; }
      &.short { background: #450A0A; color: #F87171; }
    }
  }
  .ai-dialog-score {
    font-size: 16px;
    color: #94A3B8;
    margin-bottom: 6px;
    span {
      font-size: 28px;
      font-weight: 800;
      font-family: monospace;
      margin-left: 8px;
      &.long { color: #4ADE80; }
      &.short { color: #F87171; }
    }
  }
  .ai-dialog-timeframe {
    font-size: 13px;
    color: #64748B;
    margin-bottom: 12px;
  }
  .ai-dialog-reason {
    text-align: left;
    background: #0A1118;
    border-radius: 8px;
    padding: 12px;
    margin: 12px 0;
    .reason-label { font-size: 12px; color: #818CF8; margin-bottom: 6px; font-weight: 600; }
    .reason-text { font-size: 13px; color: #CBD5E1; line-height: 1.6; }
  }
  .ai-dialog-time {
    font-size: 13px;
    color: #64748B;
    margin-top: 8px;
  }
}

.ai-alert-section {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid #1E293B;
  .ai-alert-title {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 600;
    color: #818CF8;
    margin-bottom: 8px;
  }
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

/* ============================================
   4 种布局模式
   ============================================ */

/* --- 方案 B: 紧凑全屏（一屏全展示） --- */
.layout-compact {
  .kline-page {
    min-height: calc(100vh - 64px - 20px);
    overflow-y: auto;
  }
  .kline-left {
    overflow: hidden;
    gap: 6px;
  }
  .kline-right {
    width: 260px;
    gap: 6px;
    overflow: hidden;
  }
  .quote-bar {
    padding: 0;
  }
  .quote-item {
    padding: 4px 8px;
  }
  .quote-period { font-size: 10px; margin-bottom: 0; }
  .quote-high, .quote-low { font-size: 11px; }

  /* K线主图缩小 */
  .chart-main { height: 220px !important; }
  .chart-sub { height: 80px !important; }

  /* 底部三面板更紧凑 */
  .bottom-panels {
    gap: 6px;
  }
  .bottom-panel {
    padding: 4px 8px;
    .side-title {
      font-size: 11px !important;
      margin-bottom: 4px !important;
      padding-bottom: 4px !important;
    }
  }
  .compact-ob .ob-row {
    height: 16px !important;
    line-height: 16px !important;
    font-size: 10px !important;
  }
  .compact-trades .trade-row {
    height: 16px !important;
    line-height: 16px !important;
    font-size: 10px !important;
  }
  .compact-trades .trades-stats { margin-bottom: 4px !important; }
  .compact-trades .ts-item { padding: 2px 4px !important; }
  .compact-trades .ts-label { font-size: 9px !important; }
  .compact-trades .ts-value { font-size: 11px !important; }
  .compact-trades .ts-amount { font-size: 9px !important; }
  .compact-liq .liq-bar-item {
    height: 14px !important;
    line-height: 14px !important;
    font-size: 9px !important;
  }
  .compact-liq .liq-current-price {
    font-size: 13px !important;
    margin: 0 0 4px !important;
  }

  /* 下方信息卡片横向排列（隐藏多余的，只保留关键） */
  .info-card .info-title {
    font-size: 12px !important;
    margin-bottom: 6px !important;
  }
  .period-item {
    padding: 4px !important;
  }
  .period-label { font-size: 10px !important; }
  .period-high, .period-low { font-size: 11px !important; }

  /* 涨跌参数改为3列更紧凑 */
  .rf-grid {
    grid-template-columns: repeat(5, 1fr);
    gap: 4px;
  }
  .rf-item {
    padding: 4px 2px !important;
  }
  .rf-label { font-size: 10px !important; }
  .rf-value { font-size: 12px !important; }

  /* 右侧卡片缩小 */
  .side-card {
    padding: 8px 10px !important;
  }
  .side-title {
    font-size: 12px !important;
    margin-bottom: 6px !important;
    padding-bottom: 6px !important;
  }

  /* 隐藏预警卡片节省空间 */
  .alert-card { display: none; }
}

/* --- 方案 C: K线聚焦模式 --- */
.layout-focus {
  .kline-page {
    height: calc(100vh - 64px - 20px);
    overflow: hidden;
  }
  .kline-left {
    overflow: hidden;
    gap: 8px;
  }
  .kline-right {
    width: 240px;
    gap: 8px;
    overflow: hidden;
  }

  /* K线图最大化 */
  .chart-main { height: 420px !important; }
  .chart-sub { height: 100px !important; }

  /* 底部三面板只显示一个深度盘口，其他隐藏 */
  .bottom-panels { display: none; }

  /* 下方信息卡片全部隐藏 */
  .info-card { display: none; }

  /* 右侧只显示深度+成交，其他隐藏 */
  .side-card:nth-child(3), /* 清算热力图 */
  .side-card:nth-child(4), /* 持仓量 */
  .alert-card { display: none; }

  /* 预警提醒条保留 */
  .whale-alert-bar { display: flex; }
}

/* --- 方案 D: 仪表盘模式 --- */
.layout-dashboard {
  .kline-page {
    min-height: calc(100vh - 64px - 20px);
    overflow-y: auto;
  }
  .kline-left {
    overflow: hidden;
    gap: 6px;
  }
  .kline-right {
    display: none; /* 右侧内容移到下方横向排列 */
  }

  /* K线主图中等大小 */
  .chart-main { height: 260px !important; }
  .chart-sub { height: 90px !important; }

  /* 底部三面板 + 涨跌参数 + 支撑阻力 横向铺满 */
  .bottom-panels {
    gap: 6px;
  }
  .bottom-panel {
    padding: 6px 8px;
    .side-title {
      font-size: 11px !important;
      margin-bottom: 4px !important;
      padding-bottom: 4px !important;
    }
  }

  /* 涨跌参数卡片顶部展示 */
  .rf-grid {
    grid-template-columns: repeat(5, 1fr);
    gap: 6px;
  }
  .rf-item {
    padding: 6px 4px !important;
  }
  .rf-label { font-size: 10px !important; }
  .rf-value { font-size: 13px !important; }
}

/* ============================================
   自定义可拖拽网格布局
   ============================================ */
.kline-custom-main {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
}
.kline-custom-main::-webkit-scrollbar {
